<?php
namespace Azuriom\Plugin\GamingHubCore\Services; use Azuriom\Plugin\GamingHubCore\Exceptions\ExtensionOperationFailed;
final class GitHubReleaseClient { public function __construct(private SafeExtensionHttpClient $http,private ExtensionUrlGuard $guard){} public function latest(string $repository,bool $prereleases=false):array{[$owner,$repo]=$this->guard->assertGithubRepository($repository);$releases=$this->http->json("https://api.github.com/repos/{$owner}/{$repo}/releases");foreach($releases as $release){if(($release['draft']??true)===true)continue;if(!$prereleases&&($release['prerelease']??false))continue;return $release;}throw new ExtensionOperationFailed('No stable packaged GitHub Release is available.');} public function selectAsset(array $release,string $pattern):array{$assets=$release['assets']??[];foreach($assets as $a){$name=(string)($a['name']??'');if($this->matches($pattern,$name)&&str_ends_with(strtolower($name),'.zip'))return $a;}throw new ExtensionOperationFailed('No matching packaged ZIP release asset found.');} public function checksumAsset(array $release,?string $preferred):?array{foreach(($release['assets']??[]) as $a){$n=strtolower((string)($a['name']??''));if(($preferred&&$a['name']===$preferred)||in_array($n,['sha256sums','checksums.txt'],true)||str_ends_with($n,'.sha256'))return $a;}return null;} private function matches(string $p,string $n):bool{return fnmatch($p,$n,FNM_CASEFOLD);}}
